    fr: "Bonjour ! Je suis votre copilote de voyage IA. Posez-moi des questions sur les itin\u00e9raires, arr\u00eats, h\u00f4tels ou plats locaux.",
    de: "Hallo! Ich bin Ihr KI-Reisebegleiter. Fragen Sie mich nach Routen, Rastpl\u00e4tzen, Hotels oder regionalem Essen.",
    ja: "\u3053\u3093\u306b\u3061\u306f\uff01AI\u30c8\u30e9\u30d9\u30eb\u30b3\u30d1\u30a4\u30ed\u30c3\u30c8\u3067\u3059\u3002\u30eb\u30fc\u30c8\u3001\u4f11\u61a9\u30b9\u30dd\u30c3\u30c8\u3001\u5bbf\u6cca\u5148\u3001\u3054\u5f53\u5730\u30b0\u30eb\u30e1\u306b\u3064\u3044\u3066\u8cea\u554f\u3057\u3066\u304f\u3060\u3055\u3044\u3002",
    hi: "\u0928\u092e\u0938\u094d\u0924\u0947! \u092e\u0948\u0902 \u0906\u092a\u0915\u093e AI \u092f\u093e\u0924\u094d\u0930\u093e \u0938\u0939-\u092a\u093e\u092f\u0932\u091f \u0939\u0942\u0901\u0964 \u092e\u0941\u091d\u0938\u0947 \u092e\u093e\u0930\u094d\u0917\u094b\u0902, \u0939\u093e\u0908\u0935\u0947 \u0938\u094d\u091f\u0949\u092a\u094d\u0938, \u0939\u094b\u091f\u0932 \u092f\u093e \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092d\u094b\u091c\u0928 \u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u092a\u0942\u091b\u0947\u0902\u0964",
    zh: "\u60a8\u597d\uff01\u6211\u662f\u60a8\u7684AI\u65c5\u884c\u526f\u9a7e\u3002\u6709\u5173\u8def\u7ebf\u3001\u6cbf\u9014\u670d\u52a1\u533a\u3001\u9152\u5e97\u4f4f\u5bbf\u6216\u5730\u9053\u7f8e\u98df\u90fd\u53ef\u4ee5\u95ee\u6211\u3002",
    ar: "\u0645\u0631\u062d\u0628\u0627\u064b! \u0623\u0646\u0627 \u0645\u0633\u0627\u0639\u062f \u0627\u0644\u0633\u0641\u0631 \u0627\u0644\u0630\u0643\u064a \u0627\u0644\u062e\u0627\u0635 \u0628\u0643. \u0627\u0633\u0623\u0644\u0646\u064a \u0639\u0646 \u0627\u0644\u0645\u0633\u0627\u0631\u0627\u062a \u0648\u0645\u062d\u0637\u0627\u062a \u0627\u0644\u062a\u0648\u0642\u0641 \u0648\u0627\u0644\u0641\u0646\u0627\u062f\u0642 \u0648\u0627\u0644\u0645\u0623\u0643\u0648\u0644\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629.",
    it: "Ciao! Sono il tuo Co-Pilota di viaggio AI. Chiedimi di percorsi, soste autostradali, hotel o cibo locale.",
